parameters.jsCode:
let partes = [];
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  if (Array.isArray(parsed.partes)) partes = parsed.partes;
} catch (e) {}

const categoriasValidas = ['precio', 'stock', 'envio', 'negocio', 'cierre', 'otro'];
const kitId = $('Preparar Contexto Sub-preguntas').item.json.kit_id;
const kitNombre = $('Preparar Contexto Sub-preguntas').item.json.kit_nombre;
const kitRecienConfirmado = $('Preparar Contexto Sub-preguntas').item.json.kit_recien_confirmado === true;
const cierreRecienteRaw = $('Preparar Contexto Sub-preguntas').item.json.cierre_reciente_raw;
// 2026-08-27: si al cliente ya le dijimos que este mismo kit no es compatible / no lo
// tenemos para su moto, no auto-respondemos precio/stock/detalle de ese kit -> anulamos
// kit_id para que caiga en 'otro' y escale (ver feedback-bot-aliviador-mensajes).
const incompatibleRaw = $('Preparar Contexto Sub-preguntas').item.json.incompatible_raw;
let kitBloqueadoPorIncompat = false;
try {
  const pi = typeof incompatibleRaw === 'string' ? JSON.parse(incompatibleRaw) : incompatibleRaw;
  if (pi && pi.grupo_id && kitId && Number(pi.grupo_id) === Number(kitId)) kitBloqueadoPorIncompat = true;
} catch (e) {}
const kitIdEfectivo = kitBloqueadoPorIncompat ? null : kitId;
const escapar = (s) => (s || '').toString().replace(/'/g, "''");

const limpio = partes
  .map((p) => {
    let categoria = categoriasValidas.includes(p && p.categoria) ? p.categoria : 'otro';
    if (categoria === 'precio' && !kitIdEfectivo) categoria = 'otro';
    if (categoria === 'stock' && !kitIdEfectivo) categoria = 'otro';
    return { texto: ((p && p.texto) || '').toString().trim(), categoria };
  })
  .filter((p) => p.texto.length > 0)
  .filter((p) => !(p.categoria === 'precio' && kitRecienConfirmado))
  .map((p) => ({ ...p, texto_sql: escapar(p.texto), kit_id: kitIdEfectivo, kit_nombre: kitNombre, cierre_reciente_raw: cierreRecienteRaw }));

return [{ json: { partes: limpio } }];

options.systemMessage:
Extrae del mensaje del cliente el tema puntual sobre el negocio que esta preguntando (no sobre un repuesto especifico). Respondé UNICAMENTE con un JSON valido, sin texto adicional, con este formato exacto:
{"tema": "..."}

Elegi el tema entre: ubicacion, horarios, medios_pago, envios, garantia, mayorista, otro. "mayorista" es cuando el cliente dice que tiene su propio local (lubricentro, casa de repuestos, taller) y quiere comprar para revender, no para instalar en su propia moto. Usa "otro" si es sobre el negocio pero no encaja en los anteriores. No inventes datos, solo clasifica.

parameters.jsCode:
let tema = 'otro';
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  const temasValidos = ['ubicacion', 'horarios', 'medios_pago', 'envios', 'garantia', 'mayorista', 'otro'];
  if (temasValidos.includes(parsed.tema)) tema = parsed.tema;
} catch (e) {}

const escapar = (s) => (s || '').toString().replace(/'/g, "''");
return { json: { tema_sql: escapar(tema) } };

const categoria = $('Separar Pedazos').item.json.categoria;
const texto = $('Separar Pedazos').item.json.texto;

let dato = null;
let omitir = false;
let esCierreNuevo = false;
if (categoria === 'precio') {
  const r = $('Buscar Precio Kit Pineado').item.json;
  if (r && r.precio != null) dato = 'Precio: ' + r.precio;
} else if (categoria === 'stock') {
  dato = 'Sí, tenemos stock.';
} else if (categoria === 'envio') {
  const kitEnvio = $('Buscar Envio Kit Pineado').item.json;
  if (kitEnvio && kitEnvio.envio != null) {
    dato = kitEnvio.envio;
  } else {
    const general = $('Buscar Info Negocio (Envio General)').item.json;
    if (general && general.respuesta != null) dato = general.respuesta;
  }
} else if (categoria === 'negocio') {
  const r = $('Buscar Info Negocio (Negocio)').item.json;
  if (r && r.respuesta != null) dato = r.respuesta;
} else if (categoria === 'cierre') {
  let yaEnviado = false;
  try {
    const raw = $('Separar Pedazos').item.json.cierre_reciente_raw;
    yaEnviado = !!raw;
  } catch (e) {}
  if (yaEnviado) {
    omitir = true;
  } else {
    dato = 'Dale, cualquier cosa nos escribís.';
    esCierreNuevo = true;
  }
} else {
  let compatModeloPendiente = false;
  try {
    compatModeloPendiente = $('Preparar Contexto Sub-preguntas').item.json.compat_modelo_pendiente === true;
  } catch (e) {}

  const detalle = compatModeloPendiente ? null : $('Parsear Respuesta Otro desde Detalle').item.json;
  if (!compatModeloPendiente && detalle && detalle.resuelto === true && detalle.dato) {
    dato = detalle.dato;
  } else {
    const r = $('Buscar en Conocimiento Libre (Sin Match)').item.json;
    if (r && r.respuesta != null) {
      dato = r.respuesta;
    } else {
      const g = $('Parsear Articulo Suelto (Catálogo General)').item.json;
      if (g && g.resuelto === true && g.dato) dato = g.dato;
    }
  }
}

return { json: { texto, categoria, dato_texto: dato || 'SIN_DATO', omitir, es_cierre_nuevo: esCierreNuevo } };

const mensaje = (($json.output || '').toString().trim());
const omitir = $('Consolidar Dato Resuelto').item.json.omitir === true;
const esCierreNuevo = $('Consolidar Dato Resuelto').item.json.es_cierre_nuevo === true;
const resuelto = omitir ? true : (!!mensaje && mensaje !== 'SIN_DATO');
return { json: {
  texto: $('Consolidar Dato Resuelto').item.json.texto,
  categoria: $('Consolidar Dato Resuelto').item.json.categoria,
  resuelto,
  mensaje: (resuelto && !omitir) ? mensaje : '',
  omitir,
  es_cierre_nuevo: esCierreNuevo,
} };

const todas = $json.piezas || [];
const piezas = todas.filter((p) => !p.omitir);
const prioridad = { precio: 0, stock: 1, envio: 2, negocio: 3, otro: 4 };

const noResueltas = piezas.filter((p) => !p.resuelto || !p.mensaje);
const haySinResolverReal = noResueltas.length > 0;

// Si en la misma rafaga hay alguna respuesta informativa resuelta (precio, stock, envio, negocio, otro),
// o si queda algo sin resolver (escalado en silencio), NO mandamos el "cierre".
// Decir "cualquier cosa nos escribis" mientras le estamos respondiendo info util o escalando
// es contradictorio y cierra prematuramente la charla (casos reales: conv 2318, 1036, 2809).
const hayInformativasResueltas = piezas.some(
  (p) => p.resuelto && p.mensaje && p.categoria !== 'cierre'
);
const candidatas = piezas.filter(
  (p) => p.resuelto && p.mensaje && !((haySinResolverReal || hayInformativasResueltas) && p.categoria === 'cierre')
);

const vistos = new Set();
const resueltas = candidatas
  .sort((a, b) => (prioridad[a.categoria] ?? 9) - (prioridad[b.categoria] ?? 9))
  .filter((p) => {
    if (vistos.has(p.mensaje)) return false;
    vistos.add(p.mensaje);
    return true;
  });

let mensaje1 = null, mensaje2 = null;
if (resueltas.length === 1) {
  mensaje1 = resueltas[0].mensaje;
} else if (resueltas.length >= 2) {
  mensaje1 = resueltas[0].mensaje;
  mensaje2 = resueltas.slice(1).map((p) => p.mensaje).join('\n\n');
}

const piezasSinResolver = noResueltas.map((p) => p.texto).filter(Boolean).join('; ');
const escapar = (s) => (s || '').toString().replace(/'/g, "''");

// Solo marcamos el cierre como "enviado" (dedup 24hs en Redis) si de verdad
// quedo incluido en lo que se manda -- si lo suprimimos arriba, no hay que
// pisar el dedup por algo que nunca llego al cliente.
const necesitaMarcarCierre = resueltas.some((p) => p.categoria === 'cierre' && p.es_cierre_nuevo === true);

return [{ json: {
  hayMensajes: !!mensaje1,
  mensaje1: mensaje1 || '',
  mensaje2: mensaje2 || '',
  hayMensaje2: !!mensaje2,
  haySinResolver: noResueltas.length > 0,
  piezas_sin_resolver_sql: escapar(piezasSinResolver),
  necesitaMarcarCierre,
} }];

