    dato = real.nombre + ' no lo vendemos suelto, solo como parte del combo.';
  } else {
    const precioFmt = Number(real.precio).toLocaleString('es-AR');
    dato = real.nombre + ' suelto cuesta $' + precioFmt + '.';
