// 2026-08-22: si el cliente ya recibio "no, no es compatible" (con el nuevo argumento
// tecnico cargado en chat_articulo_compatibilidad.detalle) y vuelve a insistir sobre el
// MISMO combo sin dar una moto nueva, "Identificar Necesidad" lo reclasifica igual como
// interes nuevo (kit_confiado) porque no tiene memoria de la incompatibilidad ya avisada
// -- ver conv 2486 (+5493718412887): "Pero si es de recorrido corto deberia funcionar
// igual" reinicio el saludo completo en vez de reconocer que ya se le dijo que no.
// En vez de seguir discutiendo, se escala directo a una persona (pedido explicito de
// Martin) sin volver a pinear ni mandar nada al cliente.
const identificado = $('Parsear Identificar Necesidad').item.json;

let incompatGrupoId = null, incompatModelo = null;
try {
