} catch (e) {}

const escapar = (s) => (s || '').toString().replace(/'/g, "''");

return [{ json: { modelo_moto: modeloMoto, modelo_moto_sql: escapar(modeloMoto) } }];

// 2026-08-23: si el cliente menciona su moto junto con un pedido ambiguo entre
// varios kits (candidatos), antes esto siempre preguntaba "¿a cual te referis?"
// sin usar el dato de la moto -- aunque ya supieramos que NINGUNO de los candidatos
// es compatible (ver conv 2493, +5493513732673, Wave S). Ahora se chequea la
// compatibilidad de cada candidato antes de decidir que hacer.
const identificado = $('Parsear Identificar Necesidad').item.json;
const filas = $input.all().map((item) => item.json);
const modeloMoto = $('Parsear Modelo (Candidatos)').item.json.modelo_moto;

const compatibles = [];
const incompatibles = [];
const sinDato = [];
for (const c of identificado.candidatos) {
  const fila = filas.find((f) => f.grupo_id === c.kit_id);
  if (!fila || !fila.hay_dato) { sinDato.push(c); continue; }
  if (fila.compatible === true) compatibles.push(c);
  else incompatibles.push({ ...c, detalle: fila.detalle });
}

let modo;
if (compatibles.length === 0 && sinDato.length === 0) {
  modo = 'ninguno_compatible';
} else if (compatibles.length === 1 && sinDato.length === 0) {
  modo = 'uno_compatible';
} else {
  modo = 'reducir_candidatos';
}

const candidatosValidos = [...compatibles, ...sinDato];
const unicoGrupoId = modo === 'uno_compatible' ? compatibles[0].kit_id : null;

return [{ json: { modo, modelo_moto: modeloMoto, candidatos_validos: candidatosValidos, unico_grupo_id: unicoGrupoId } }];

const candidatos = $json.candidatos_validos || [];
const mensaje = candidatos.length === 1
  ? `¿Te referís a ${candidatos[0].nombre}?`
  : `¿Te referís a ${candidatos.map((c) => c.nombre).join(' o a ')}?`;

return [{ json: { mensaje } }];

