parameters.jsCode:
function normalizar(s) {
  return (s || '').toString().toLowerCase()
    .replace(/[áàä]/g,'a').replace(/[éèë]/g,'e').replace(/[íìï]/g,'i')
    .replace(/[óòö]/g,'o').replace(/[úùü]/g,'u').replace(/ñ/g,'n');
}
function tokenizar(s) {
  return normalizar(s).replace(/[^a-z0-9]+/g, ' ').split(' ').filter((t) => t.length >= 3);
}
function precioLinea(real) {
  if (real.precio === null || real.precio === undefined) {
    return real.nombre + ' no lo vendemos suelto, solo como parte del combo.';
  }
  const precioFmt = Number(real.precio).toLocaleString('es-AR');
  return real.nombre + ' suelto cuesta $' + precioFmt + '.';
}

let resuelto = false, articuloIds = [], dato = '';
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  resuelto = parsed.resuelto === true;
  const idsRaw = Array.isArray(parsed.articulo_ids)
    ? parsed.articulo_ids
    : (parsed.articulo_id !== undefined && parsed.articulo_id !== null ? [parsed.articulo_id] : []);
  articuloIds = idsRaw.filter((x) => x !== null && x !== undefined).map(Number).filter((n) => Number.isFinite(n));
  dato = (parsed.dato || '').toString().trim();
} catch (e) {}

if (resuelto && articuloIds.length > 0) {
  const articulos = $('Buscar Detalle Grupo Pineado (Con Modelo)').item.json.articulos || [];
  const reales = articuloIds
    .map((id) => articulos.find((a) => Number(a.id) === id))
    .filter((a) => a);

  if (reales.length === 0) {
    resuelto = false;
    dato = '';
  } else if (reales.length === 1) {
    const real = reales[0];
    const rivales = articulos.filter((a) => a.categoria === real.categoria && Number(a.id) !== real.id);
    let distingue = true;
    if (rivales.length > 0) {
      const textoCliente = normalizar(($('Parsear Modelo Grupo').item.json.resto_mensaje || $('Unir Mensajes').item.json.texto_completo) || '');
      const tokensPropios = new Set(tokenizar([real.alias, real.nombre, real.variante].join(' ')));
      const tokensRivales = new Set(rivales.flatMap((r) => tokenizar([r.alias, r.nombre, r.variante].join(' '))));
      const exclusivosPropios = [...tokensPropios].filter((t) => !tokensRivales.has(t));
      distingue = exclusivosPropios.some((t) => textoCliente.includes(t));
    }
    if (!distingue) {
      resuelto = false;
      dato = '';
    } else {
      dato = precioLinea(real);
    }
  } else {
    // El cliente pidio explicitamente mas de una variante -- no hay ambiguedad que resolver,
    // se nombraron todas las que pidio. Un renglon de precio por cada una.
    dato = reales.map(precioLinea).join(' ');
  }
}

if (!dato) resuelto = false;

return { json: { resuelto, dato } };

