{{ $('Detectar Interes de Compra').item.json.interes_compra_texto_original }}

Frase que se detecto: "{{ $('Detectar Interes de Compra').item.json.interes_compra_frase }}"

parameters.jsCode:
// Gate de IA para intencion de compra (fix 2026-08-28, conv 2385 / +5493735466916).
// La lista de frases de "Detectar Interes de Compra" solo dispara la sospecha; este
// paso confirma con IA acotada si es una decision real o una pregunta condicional
// ("...si lo compro", "lo pago cuando llega?"). Fallback conservador: si la IA falla,
// se respeta el match de palabra clave (se pausa igual -- un falso positivo se
// arregla con /bot on, una venta perdida no).
let intencionReal = true;
try {
  const raw = ($json.output || '{}').toString().replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(raw);
  if (typeof parsed.intencion_real === 'boolean') intencionReal = parsed.intencion_real;
} catch (e) {}

const base = $('Detectar Interes de Compra').first().json;
return [{ json: { ...base, interes_compra: intencionReal } }];

// Si YA hay un pack simple pineado (no un grupo en resolucion) y la IA de
// "Identificar Necesidad" intento pinear OTRO kit / re-saludar / repreguntar
// candidatos, lo ignoramos y forzamos 'ninguno' -> el mensaje lo maneja el
// partidor de sub-preguntas con el kit pineado como contexto, sin pisar el pin
// ni mandar una bienvenida que nadie pidio.
// (fix 2026-08-28, conv 2385: "Y lo pago cuando llega?" con Kit 170 pineado
//  disparaba la bienvenida del Combo Escape+Leva). Misma logica de deteccion
//  de 'mismo kit / mismo grupo' que "Chequear Kit Ya Resuelto".
const parsed = $json;
let pinKitId = null, pinEsGrupo = null;
try {
  const pin = $('Parsear Kit Pineado').item.json;
  pinKitId = pin.kit_id; pinEsGrupo = pin.es_grupo;
} catch (e) {}

if (pinEsGrupo === false && pinKitId) {
  const identificadoId = parsed.kit_id;
  let mismoKit = identificadoId === pinKitId;
  if (!mismoKit && identificadoId) {
    const grupos = ($('Buscar Kits Activos').item.json.grupos) || [];
    const grupoDelPin = grupos.find((g) => (g.variantes || []).some((v) => v.id === pinKitId));
    if (grupoDelPin && grupoDelPin.id === identificadoId) mismoKit = true;
  }
  if (!mismoKit) {
    return [{ json: { tipo: 'ninguno', kit_id: null, kit_nombre: '', candidatos: [], mensaje: '' } }];
  }
}
return [{ json: parsed }];

// El buffer de Redis guarda mas nuevo primero (push = LPUSH), por eso se
// invierte antes de unir. Si el cliente mando "Hola" y despues "quiero el
// combo 110 a 120" en dos mensajes seguidos, acá quedan juntos en un solo
// texto para que el resto del flujo los trate como una sola consulta.
//
// primer_mensaje / resto_mensaje (Fase 10, 2026-08-13): ademas del texto
// unido, se expone por separado el PRIMER mensaje de la rafaga y todo lo
// que vino despues -- necesario para que el matching de plantilla exacta
// (Clasificar Mensaje) se compare solo contra el primer mensaje, sin que
// una frase agregada a continuacion (ej. "que valen") rompa el match.
//
// referral (2026-08-22): Meta solo manda el dato del anuncio (body, headline,
// welcome_message, etc.) pegado al primer mensaje de una conversacion nueva.
// Si ese primer mensaje cae en la misma rafaga que el siguiente (caso real,
// conv 2475), el mensaje que dispara el procesamiento es el ULTIMO de la
// rafaga, que no trae referral -- por eso hay que rescatarlo de cualquier
// item del buffer, no solo del webhook actual. Deberia haber a lo sumo un
// referral por rafaga (solo lo trae el primer mensaje real de la conversacion).
const raw = $('Traer Buffer').item.json.message || [];
const mensajesOrdenados = raw
  .slice()
  .reverse()
  .map((s) => {
    try {
      const obj = typeof s === 'string' ? JSON.parse(s) : s;
      return obj?.message || '';
    } catch (e) {
      return String(s);
    }
  });

const textoCompleto = mensajesOrdenados.join('\n');
const primerMensaje = mensajesOrdenados[0] || '';
const restoMensaje = mensajesOrdenados.slice(1).join('\n');

let referral = null;
for (const s of raw) {
  try {
    const obj = typeof s === 'string' ? JSON.parse(s) : s;
    if (obj && obj.referral) { referral = obj.referral; break; }
  } catch (e) {}
}

return [{ json: { texto_completo: textoCompleto, primer_mensaje: primerMensaje, resto_mensaje: restoMensaje, referral } }];

// Clasificacion sin IA, en orden de confianza:
//  1) plantilla exacta: el PRIMER mensaje de la rafaga coincide letra por
//     letra (normalizado) con una linea del campo "Plantillas exactas de
//     Instagram/Meta Ads" -- de un pack SIN grupo (kit unico, se pinea
//     directo) o de un GRUPO (2026-08-21, migracion al catalogo nuevo: el
//     grupo se pinea en estado "esperando_moto", el pack final se resuelve
//     despues via el gate de compatibilidad + pregunta de variante -- ver
//     n8n-workflows/CHATWOOT-BOT-CONTEXTO.md).
//  2) referral de Meta Ads: cuando el boton del anuncio manda un texto
//     generico ("¡Hola! Quiero mas informacion") en vez de la plantilla fija,
//     Meta igual pega la metadata real del anuncio (headline/body) al
//     mensaje -- si coincide (normalizado) con una linea de "Textos de
//     anuncio de Meta Ads" de un pack o grupo, identifica el kit igual que
//     la plantilla exacta. Confirmado 2026-08-26 que ese headline/body es
//     estable por campana (mismo texto en cada clic) -- ver
//     n8n-workflows/CHATWOOT-BOT-CONTEXTO.md.
//     A diferencia de la plantilla exacta (que por definicion consume TODO
//     el primer mensaje, texto literal conocido), el referral matchea por
//     metadata sin mirar el texto -- el cliente pudo haber escrito cualquier
//     cosa como primer mensaje, incluido un pedido puntual de otro producto
//     (caso real 2026-08-26, conv 2779, +5493515913795: referral del Kit 170
//     pero el cliente pidio un piston especifico para otra moto). Por eso,
//     si el mensaje tiene contenido propio (no es puro saludo/relleno), ese
//     texto completo se manda como resto_mensaje para que pase por el mismo
//     chequeo de continuidad de tema que ya usa la plantilla exacta (Fase
//     10) -- si la IA dice "tema distinto", no se manda el saludo del kit a
//     ciegas y escala normal.
//  3) si no matcheo nada pero el mensaje es un saludo sin pedido especifico
//     -> saludo
//  4) cualquier otra cosa -> sin_match (todavia sin manejar)
//
// Por que no keywords: la cobertura de keywords (ej. alias "kit 120" de
// 2 palabras sueltas) matcheaba mensajes que solo tenian esas palabras
// dispersas en el texto sin relacion real, ej. una consulta de precio de
// piezas sueltas ("...consulto que sale el kit de 120 tapa de cilindro
// cdi...") disparaba el saludo del combo como si fuera la respuesta
// correcta. Se probo agregar una guarda por palabras de precio y no alcanzo
// — el usuario pidio sacar "keywords" del matching por completo y dejar
// SOLO la plantilla exacta, que no tiene ambiguedad posible porque es
// texto literal.
const packs = $('Buscar Kits Activos').item.json.packs || [];
const grupos = $('Buscar Kits Activos').item.json.grupos || [];
const referral = $('Unir Mensajes').item.json.referral || null;
const mensaje = ($('Unir Mensajes').item.json.texto_completo || '').toString();
const primerMensaje = ($('Unir Mensajes').item.json.primer_mensaje || '').toString();
const restoMensaje = ($('Unir Mensajes').item.json.resto_mensaje || '').toString().trim();

const STOPWORDS = new Set([
  'para','con','del','las','los','una','uno','que','por','sus','esa','ese','esta','este','hay',
  'mas','tiene','tienen','quiero','necesito','busco','tengo','como','cual','cuanto',
  'hola','holis','buenas','buenos','buen','dias','dia','tardes','tarde','noches','noche','tal',
  'hey','alo','informacion','info','ayuda','favor','porfa','porfavor','consultar','saber','onda',
  'todo','bien','gracias','disculpa','disculpe','perdon',
  'enlace',
]);

const normalizar = (s) => s.toString().trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ');

function tokens(txt) {
  const plano = normalizar(txt).replace(/[^a-z0-9]+/g, ' ');
  const vistos = new Set();
  for (const t of plano.split(' ')) {
    const base = t.replace(/(.)\1+/g, '$1');
    if (base.length < 3 || STOPWORDS.has(base)) continue;
    vistos.add(base.replace(/s$/, ''));
  }
  return [...vistos];
}

const mensajeNorm = normalizar(mensaje);
const primerMensajeNorm = normalizar(primerMensaje);
const mensajeTokens = tokens(mensaje);

function salidaKit(tipo, kit, restoParaContinuidad) {
  return [{ json: { tipo: 'kit', deteccion: tipo, kit_id: kit.id, kit_nombre: kit.nombre, mensaje_bienvenida: kit.mensaje_bienvenida, foto_url: kit.foto_url || null, resto_mensaje: restoParaContinuidad } }];
}

function salidaGrupo(tipo, grupo, restoParaContinuidad) {
  return [{ json: { tipo: 'grupo', deteccion: tipo, grupo_id: grupo.id, grupo_nombre: grupo.nombre, mensaje_bienvenida: grupo.mensaje_bienvenida, foto_url: grupo.foto_url || null, resto_mensaje: restoParaContinuidad } }];
}

// Para plantilla exacta, el "resto" de siempre (lo que vino DESPUES del
// primer mensaje en la misma rafaga) alcanza -- el primer mensaje ya fue
// consumido por completo por el match literal. Para referral, si el
// mensaje tiene contenido propio, no hay nada "consumido" -- se manda el
// texto completo para que la continuidad de tema lo evalue entero.
const tieneContenidoPropio = mensajeTokens.length > 0;
const restoParaReferral = tieneContenidoPropio ? mensaje : restoMensaje;

// 1) Plantilla exacta (solo contra el primer mensaje de la rafaga)
for (const pack of packs) {
  const plantillas = (pack.plantillas_bienvenida || '').split('\n').map(normalizar).filter(Boolean);
  if (plantillas.includes(primerMensajeNorm)) return salidaKit('plantilla_exacta', pack, restoMensaje);
}
for (const grupo of grupos) {
  const plantillas = (grupo.plantillas_bienvenida || '').split('\n').map(normalizar).filter(Boolean);
  if (plantillas.includes(primerMensajeNorm)) return salidaGrupo('plantilla_exacta', grupo, restoMensaje);
}

// 2) Referral de Meta Ads (headline o body del anuncio real) -- pero SOLO si
// todavia NO hay un kit pineado para este telefono. Meta sigue pegando el
// referral del primer anuncio en mensajes posteriores de la MISMA charla,
// no solo en el que la abrio (confirmado 2026-08-26, conv 2495,
// +5492954686592: un audio y un "Okey" de mitad de conversacion trajeron el
// mismo referral del primer mensaje y volvieron a mandar la bienvenida
// completa con foto de nuevo) -- no se puede confiar en "llego referral"
// como sinonimo de "recien tocaron el anuncio". Ver
// n8n-workflows/CHATWOOT-BOT-CONTEXTO.md.
const yaHayKitPineado = Boolean($('Leer Kit Pineado (Pre-Referral)').item.json.kit_pineado_check_raw);
if (referral && !yaHayKitPineado) {
  // Solo se compara el BODY (descripcion) del anuncio, NUNCA el headline
  // (titulo). Meta reusa el mismo titulo-slogan entre campanias distintas
  // -- caso real 2026-08-27, conv 2818 (+5492227678179): el anuncio del
  // "Combo Escape PWR + Leva" y el de "Tapa CDI" comparten el headline
  // "GANA MAS RENDIMIENTO EN TU 110!", y el match por headline pineaba
  // Tapa CDI para alguien que venia por el escape. La descripcion si es
  // especifica de cada campania.
  const bodyNorm = normalizar(referral.body || '');
  if (bodyNorm) {
    for (const pack of packs) {
      const anuncios = (pack.plantillas_referral || '').split('\n').map(normalizar).filter(Boolean);
      if (anuncios.includes(bodyNorm)) return salidaKit('referral', pack, restoParaReferral);
    }
    for (const grupo of grupos) {
      const anuncios = (grupo.plantillas_referral || '').split('\n').map(normalizar).filter(Boolean);
      if (anuncios.includes(bodyNorm)) return salidaGrupo('referral', grupo, restoParaReferral);
    }
  }
}

// 3) Saludo sin pedido especifico: tiene alguna palabra de saludo Y no le
// quedan palabras de contenido despues de sacar saludo/relleno.
const GREETING_WORDS = ['hola', 'holis', 'buenas', 'buenos', 'que tal', 'hey', 'alo'];
const tieneSaludo = GREETING_WORDS.some((w) => mensajeNorm.includes(w));
if (tieneSaludo && mensajeTokens.length === 0) {
  return [{ json: { tipo: 'saludo' } }];
}

// 4) Sin match
return [{ json: { tipo: 'sin_match' } }];

// 2026-08-21 (migracion al catalogo nuevo): el valor pineado en Redis ahora
// puede ser 1) un pack final ya resuelto ({ kit_id, kit_nombre }, forma de
// siempre) o 2) un grupo en resolucion de variante ({ grupo_id, estado,
// modelo_moto? }, forma nueva). Los campos kit_id/kit_nombre se mantienen
// identicos al comportamiento de siempre para no romper nada rio abajo que
// ya los lee.
let kitId = null, kitNombre = '';
let esGrupo = false, grupoId = null, estado = null, modeloMoto = '';
try {
  const raw = $json.kit_pineado_raw || '{}';
  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (parsed.grupo_id !== undefined && parsed.grupo_id !== null) {
    esGrupo = true;
    grupoId = Number(parsed.grupo_id);
    estado = (parsed.estado || '').toString();
    modeloMoto = (parsed.modelo_moto || '').toString();
  } else {
    kitId = parsed.kit_id ?? null;
    kitNombre = (parsed.kit_nombre || '').toString();
  }
} catch (e) {}
return [{ json: { kit_id: kitId, kit_nombre: kitNombre, es_grupo: esGrupo, grupo_id: grupoId, estado, modelo_moto: modeloMoto } }];

let esCompatibilidad = false, modeloMoto = '', cilindrada = '', restoMensaje = null;
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  esCompatibilidad = parsed.es_compatibilidad === true;
  modeloMoto = (parsed.modelo_moto || '').toString().trim();
  cilindrada = (parsed.cilindrada || '').toString().trim();
  if (esCompatibilidad) restoMensaje = (parsed.resto_mensaje || '').toString().trim();
} catch (e) {}

const escapar = (s) => s.replace(/'/g, "''");

return [{
  json: {
    es_compatibilidad: esCompatibilidad,
    modelo_moto: modeloMoto,
    modelo_moto_sql: escapar(modeloMoto),
    cilindrada: cilindrada,
    resto_mensaje: restoMensaje,
    kit_id: $('Parsear Kit Pineado').item.json.kit_id,
    kit_nombre: $('Parsear Kit Pineado').item.json.kit_nombre,
  }
}];

