let preguntaId = null, compatible = null, detalle = '', mensajeCliente = '', confianza = 'baja';
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  preguntaId = parsed.pregunta_id ?? null;
  compatible = typeof parsed.compatible === 'boolean' ? parsed.compatible : null;
  detalle = (parsed.detalle || '').toString();
  mensajeCliente = (parsed.mensaje_cliente || '').toString();
  confianza = parsed.confianza === 'alta' ? 'alta' : 'baja';
} catch (e) {}

const pendientes = $('Buscar Preguntas Pendientes').item.json.pendientes || [];
let match = pendientes.find((p) => p.id === preguntaId) || null;
if (!match && pendientes.length === 1) match = pendientes[0];
if (!match || compatible === null || !mensajeCliente) confianza = 'baja';

const escapar = (s) => (s || '').toString().replace(/'/g, "''");

return [{
  json: {
    confianza,
    pregunta_id: match ? match.id : null,
    kit_id: match ? match.kit_id : null,
    es_grupo: match ? Boolean(match.es_grupo) : false,
    kit_sql: match ? escapar(match.kit) : '',
    modelo_moto_sql: match ? escapar(match.modelo_moto) : '',
    compatible,
    detalle_sql: escapar(detalle),
    mensaje_cliente: mensajeCliente,
  },
}];

let kitId = null, kitNombre = null;
try {
  const k = $('Parsear Kit Pineado').item.json;
  if (k && k.kit_id) { kitId = k.kit_id; kitNombre = k.kit_nombre || null; }
} catch (e) {}

let kitRecienConfirmado = false;
try {
  $('Marcar Kit Pineado').item;
  kitRecienConfirmado = true;
} catch (e) {}
try {
  $('Enviar Saludo Kit (Identificar Necesidad)').item;
  kitRecienConfirmado = true;
} catch (e) {}
try {
  // 2026-08-22: el pack final de un GRUPO tambien se acaba de confirmar (precio ya dicho
  // en el mensaje de bienvenida) cuando el resto de la rafaga cae aca -- ver conv 2462
  // (+5493854098485): "Corto es" + "Me pasas fotos del cabezal" pegados, el precio no
  // deberia repetirse si el resto trae ademas una pregunta de precio.
  $('Marcar Pack Final Pineado').item;
  kitRecienConfirmado = true;
} catch (e) {}

let compatModeloPendiente = false;
try {
  const c = $('Parsear Pregunta Compatibilidad').item.json;
  if (c && c.es_compatibilidad === true && (c.modelo_moto || '').toString().trim() !== '') {
    compatModeloPendiente = true;
  }
} catch (e) {}

let textoParaDividir = null;
try {
  const c = $('Parsear Pregunta Compatibilidad').item.json;
  if (c && typeof c.resto_mensaje === 'string') textoParaDividir = c.resto_mensaje;
} catch (e) {}
if (textoParaDividir === null) {
  textoParaDividir = $('Clasificar Mensaje (sin IA)').item.json.resto_mensaje || $('Unir Mensajes').item.json.texto_completo;
}

let cierreRecienteRaw = null;
try {
  cierreRecienteRaw = $('Buscar Cierre Reciente (Rafaga)').item.json.cierre_reciente_raw;
} catch (e) {}

let incompatibleRaw = null;
try {
  incompatibleRaw = $('Leer Incompatibilidad Reciente (Rafaga)').item.json.incompatible_raw;
} catch (e) {}

let ultimoMensajeNuestro = '';
try {
  ultimoMensajeNuestro = $('Extraer Ultimo Mensaje Nuestro').first().json.ultimo_mensaje_nuestro || '';
} catch (e) {}

return [{ json: { kit_id: kitId, kit_nombre: kitNombre, texto_para_dividir: textoParaDividir, kit_recien_confirmado: kitRecienConfirmado, compat_modelo_pendiente: compatModeloPendiente, ultimo_mensaje_nuestro: ultimoMensajeNuestro, cierre_reciente_raw: cierreRecienteRaw, incompatible_raw: incompatibleRaw } }];

