return [{ json: { ...$json, kit_ya_resuelto: kitYaResuelto } }];

// 2026-08-22: mismo parseo que "Parsear Resolver Variante", instancia aislada para la
// rama "esperando moto" (ver conv 1097 -- el cliente dio "Recorrido corto" en el mismo
// mensaje que la moto, antes de que se le preguntara, y el bot volvia a preguntar
// ignorando lo ya dicho). No se reusa el nodo compartido porque su salida false va a
// "Enviar Repregunta Variante" (marco de "ya te pregunte y no entendi"), que no aplica
// aca (todavia no se pregunto nada).
let packId = null;
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  const id = Number(parsed.pack_id);
