} catch (e) {}

const grupoId = $('Parsear Kit Pineado').item.json.grupo_id;
const variantes = (($('Buscar Kits Activos').item.json.grupos || []).find((g) => g.id === grupoId)?.variantes) || [];
const pack = packId !== null ? variantes.find((v) => v.id === packId) : null;

