let packId = null;
try {
  const raw = ($json.output || '{}').toString().trim();
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  const id = Number(parsed.pack_id);
  const variantesValidas = $('Buscar Variantes del Grupo (Respuesta Equipo)').item.json.variantes || [];
  const idsValidos = new Set(variantesValidas.map((v) => v.id));
  if (idsValidos.has(id)) packId = id;
} catch (e) {}

const variantes = $('Buscar Variantes del Grupo (Respuesta Equipo)').item.json.variantes || [];
const pack = packId !== null ? variantes.find((v) => v.id === packId) : null;

return [{
  json: {
    pack_id: packId,
    pack_nombre: pack ? pack.nombre : '',
    mensaje_bienvenida: pack ? pack.mensaje_bienvenida : '',
    foto_url: pack ? (pack.foto_url || null) : null,
  }
}];

const text = ($json.text || '').toString().trim();
let esUtil = text.length > 0;

// Alucinacion tipica de Whisper con audio poco claro o con ruido: en vez de
// fallar, inventa la misma silaba/palabra repetida muchas veces (ej.
// "Pa pa pa pa pa pa pa pa"). Si una sola palabra domina la mayoria del
// texto, no es un mensaje real -- tratamos esto igual que un audio fallido
// en vez de dejarlo pasar como si el cliente no hubiera dicho nada (caso
// real: conv 2593, +5493537323297, 4 audios seguidos con este patron
// hicieron que el bot repitiera la misma repregunta sin parar).
if (esUtil) {
  const palabras = text.toLowerCase().split(/[^a-z0-9áéíóúñ]+/i).filter(Boolean);
  if (palabras.length >= 8) {
    const conteos = {};
    for (const p of palabras) conteos[p] = (conteos[p] || 0) + 1;
    const maxRepeticiones = Math.max(...Object.values(conteos));
    if (maxRepeticiones / palabras.length >= 0.7) esUtil = false;
  }
}

// Frases fijas que Whisper alucina en silencio/ruido, sin relacion al audio
// real (conocidas, no dependen del idioma del prompt).
const BOILERPLATE = [/subt[íi]tulos realizados por/i, /amara\.org/i, /suscr[íi]bete/i, /gracias por ver/i];
if (BOILERPLATE.some((rx) => rx.test(text))) esUtil = false;

return [{ json: { text, es_util: esUtil } }];

options.systemMessage:
