  },
}];

// Deteccion deterministica (sin IA) de intencion de compra explicita, solo
// corre cuando ya hay un kit pineado (bienvenida/precio ya mandados). Frases
// tipo "lo quiero", "como lo pago" etc -- si matchea, el resto del flujo
// (compatibilidad, variante, etc.) se salta por completo y la conversacion
// pasa a manejo humano (ver rama nueva "Interes de Compra").
const texto = ($('Clasificar Mensaje (sin IA)').item.json.resto_mensaje || $('Unir Mensajes').item.json.texto_completo || '');

function normalizar(s) {
  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const textoNorm = normalizar(texto);

const PALABRAS_INTERES_COMPRA = [
  'lo quiero', 'la quiero', 'los quiero', 'las quiero',
  'quiero comprarlo', 'quiero comprarla', 'quiero comprar',
  'lo compro', 'la compro',
  'me lo llevo', 'me la llevo',
  'como lo pago', 'como pago', 'como hago para pagar',
  'como hago para comprarlo', 'como hago para comprar',
  'quiero pagarlo', 'quiero pagarla',
  'hago la transferencia', 'te hago la transferencia', 'mando la transferencia',
  'hago la sena', 'dejo la sena',
  'quiero reservarlo', 'quiero reservarla', 'quiero reservar', 'como reservo',
  'donde lo retiro', 'como lo retiro',
  'numero de cuenta', 'cbu',
  'me interesa',
];

const match = PALABRAS_INTERES_COMPRA.find((p) => textoNorm.includes(p));

return [{
  json: {
    ...$json,
    interes_compra: Boolean(match),
    interes_compra_frase: match || '',
    interes_compra_texto_original: texto,
  },
}];

// Suma "posible venta" a las etiquetas que ya tenga la conversacion, sin
// pisar las existentes (el endpoint de Chatwoot reemplaza la lista entera).
const existentes = ($json.payload || []);
const set = new Set(existentes);
set.add('posible venta');
return [{ json: { labels: Array.from(set) } }];

